/* Editorial operating system: Activity preserves the decision, conversation, and outcome as one calm return path. */
/* Editorial operating system: Activity turns specific founder learning into a bounded next commitment, using existing records rather than duplicate task state. */
import { useEffect, useMemo, useState } from "react";
import { ArrowLeft, ArrowRight, CalendarPlus, Check, MessageSquare, Search } from "lucide-react";
import { Link } from "wouter";
import { SectionLabel, SignalTag } from "../components/site";
import { useLocale } from "../contexts/LocaleContext";
import { getCustomerEvidenceRecords, getWorkflowRecords, removeWorkflowRecord, upsertWorkflowRecord, type WorkflowRecord } from "../lib/workflowRecords";
import { setWeeklyPrimaryBet } from "../lib/weeklyPrimaryBet";
import { ProductShell } from "./ProductFlows";
import { EventFollowUpDraftDesk } from "../components/EventFollowUpDraftDesk";

type ActivityFilter = "all" | "decision" | "event" | "application" | "introduction";

function recordKindLabel(record: WorkflowRecord, t: (en: string, ar: string) => string) {
  if (record.kind === "decision") return t("Decision", "قرار");
  if (record.kind === "event") return t("Event", "فعالية");
  if (record.kind === "introduction") return t("Introduction", "مقدمة");
  return t("Application", "طلب");
}

function introductionStatusLabel(record: WorkflowRecord, t: (en: string, ar: string) => string) {
  if (record.status === "introduced") return t("Connected", "تم الربط");
  if (record.status === "completed") return t("Conversation reflected", "تم توثيق المحادثة");
  return t("Brief in review", "الموجز قيد المراجعة");
}

type EvidenceLane = "quote" | "workaround" | "commitment";

function evidenceValue(record: WorkflowRecord, lane: EvidenceLane) {
  const evidence = record.customerEvidence;
  if (!evidence) return "";
  if (lane === "quote") return evidence.quote;
  if (lane === "workaround") return evidence.workaround;
  return evidence.action;
}

function normalizedEvidence(value: string) {
  return value.trim().toLocaleLowerCase().replace(/[“”"'،,.!?؛:]/g, "").replace(/\s+/g, " ");
}

type LearningFilter = "all" | "keep" | "change" | "stop";

type ArchiveOutcomeFilter = "all" | "open" | "keep" | "change" | "stop";
type ArchiveSourceFilter = "all" | "tool" | "workspace";

function decisionSource(record: WorkflowRecord, t: (en: string, ar: string) => string) {
  if (!record.href.startsWith("/tools/")) return t("Workspace decision", "قرار مساحة العمل");
  const slug = record.href.split("/").filter(Boolean).at(-1) ?? "";
  const labels: Record<string, [string, string]> = {
    pricing: ["Pricing decision", "قرار التسعير"],
    "saas-health": ["SaaS health", "صحة SaaS"],
    "founder-diagnostic": ["Founder diagnostic", "تشخيص المؤسس"],
    "unit-economics": ["Unit economics", "اقتصاديات الوحدة"],
    "retention-recovery": ["Retention recovery", "استعادة الاحتفاظ"],
    "activation-evidence": ["Activation evidence", "دليل التفعيل"],
    "gtm-map": ["GTM channel map", "خريطة قناة GTM"],
    "positioning-evidence": ["Positioning evidence", "دليل التموضع"],
    "customer-evidence": ["Customer evidence", "دليل العميل"],
    "market-map": ["Market map", "خريطة السوق"],
    "survival-calculator": ["Runway", "المدرج النقدي"],
  };
  const label = labels[slug] ?? ["Founder tool", "أداة المؤسس"];
  return t(label[0], label[1]);
}

function archiveExcerpt(record: WorkflowRecord, t: (en: string, ar: string) => string) {
  const value = record.evidence || record.weeklyReflection || record.nextAction || record.operatingPrinciple?.rule || "";
  if (!value) return t("No separate evidence note was retained. Reopen the source before reusing this decision.", "لم تُحتفظ بملاحظة دليل منفصلة. أعد فتح المصدر قبل إعادة استخدام هذا القرار.");
  return value.length > 238 ? `${value.slice(0, 235).trim()}…` : value;
}

type EventObservationLane = "decision-moved" | "useful-connection" | "useful-learning" | "no-useful-outcome" | "unclassified";

function CrossEventObservationReview({ records }: { records: WorkflowRecord[] }) {
  const { t, isRTL, formatNum } = useLocale();
  const notes = records.filter((record) => record.kind === "event" && Boolean(record.eventOutcomeNote)).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  const lanes: Array<{ id: EventObservationLane; label: string; labelAr: string; title: string; titleAr: string; copy: string; copyAr: string }> = [
    { id: "decision-moved", label: "DECISION CONTEXT", labelAr: "سياق القرار", title: "Notes saved beside a decision.", titleAr: "ملاحظات حُفظت بجانب قرار.", copy: "Read each room note as source context before you decide whether it changes the linked work.", copyAr: "اقرأ كل ملاحظة غرفة كسياق مصدر قبل أن تقرر ما إذا كانت تغير العمل المرتبط." },
    { id: "useful-connection", label: "CONNECTION CONTEXT", labelAr: "سياق الاتصال", title: "Notes that may guide a conversation.", titleAr: "ملاحظات قد توجه محادثة.", copy: "These observations remain room notes, not proof that a new relationship or commitment occurred.", copyAr: "تظل هذه الملاحظات ملاحظات غرفة، وليست دليلا على أن علاقة أو التزاما جديدا قد حدث." },
    { id: "useful-learning", label: "LEARNING CONTEXT", labelAr: "سياق التعلم", title: "Notes worth taking back to the field.", titleAr: "ملاحظات تستحق أن تعود إلى الميدان.", copy: "Choose one source note if you want to ask a fresh customer question. Do not merge the notes into a verdict.", copyAr: "اختر ملاحظة مصدر واحدة إذا أردت طرح سؤال عميل جديد. لا تدمج الملاحظات في حكم." },
    { id: "no-useful-outcome", label: "NO OUTCOME CLAIMED", labelAr: "لا توجد نتيجة مُدعاة", title: "Retained notes without a claimed result.", titleAr: "ملاحظات محتفظ بها من دون نتيجة مُدعاة.", copy: "Keep the room context visible without treating the absence of a result as a failure signal.", copyAr: "أبقِ سياق الغرفة ظاهرا من دون التعامل مع غياب النتيجة كإشارة فشل." },
    { id: "unclassified", label: "UNCLASSIFIED NOTE", labelAr: "ملاحظة غير مصنفة", title: "Factual room notes awaiting a label.", titleAr: "ملاحظات غرفة واقعية تنتظر تصنيفا.", copy: "Revisit the event to name the observation’s role before you use it in another workflow.", copyAr: "عد إلى الفعالية لتسمي دور الملاحظة قبل استخدامها في مسار عمل آخر." },
  ];
  const laneFor = (record: WorkflowRecord): EventObservationLane => record.eventOutcome ?? "unclassified";
  const dateLabel = (record: WorkflowRecord) => new Intl.DateTimeFormat(isRTL ? "ar-EG" : "en-GB", { month: "short", day: "numeric" }).format(new Date(record.eventOutcomeAt ?? record.updatedAt));
  if (notes.length < 2) return null;
  return <section className="cross-event-observation-review" aria-labelledby="cross-event-observation-review-title"><header className="cross-event-observation-review__heading"><div><SectionLabel>{t("Cross-event observation review", "مراجعة الملاحظات عبر الفعاليات")}</SectionLabel><h2 id="cross-event-observation-review-title">{t("Read the room notes beside one another before you name a shared lesson.", "اقرأ ملاحظات الغرف بجانب بعضها قبل أن تسمي درسا مشتركا.")}</h2><p>{t("This review groups only retained factual notes by the outcome label you saved. It does not count agreement, infer a pattern, or produce a conclusion.", "تجمع هذه المراجعة فقط الملاحظات الواقعية المحتفظ بها حسب تسمية النتيجة التي حفظتها. لا تعد الاتفاق ولا تستنتج نمطا ولا تنتج استنتاجا.")}</p></div><div className="cross-event-observation-review__metric"><strong>{formatNum(notes.length)}</strong><span>{t("room notes", "ملاحظات غرفة")}</span></div></header><div className="cross-event-observation-review__boundary"><span className="mono">{t("SYNTHESIS BOUNDARY", "حد التركيب")}</span><p>{t("A grouping is a review aid, not evidence that rooms agree. Open one source if you want to take a question into Customer Evidence.", "التجميع وسيلة للمراجعة، وليس دليلا على اتفاق الغرف. افتح مصدرا واحدا إذا أردت حمل سؤال إلى دليل العميل.")}</p></div><div className="cross-event-observation-review__lanes">{lanes.map((lane) => { const laneNotes = notes.filter((record) => laneFor(record) === lane.id); if (!laneNotes.length) return null; return <article key={lane.id} className={`is-${lane.id}`}><header><span className="mono">{t(lane.label, lane.labelAr)}</span><strong>{formatNum(laneNotes.length)}</strong></header><div className="cross-event-observation-review__lane-copy"><h3>{t(lane.title, lane.titleAr)}</h3><p>{t(lane.copy, lane.copyAr)}</p></div><div className="cross-event-observation-review__records">{laneNotes.slice(0, 3).map((record, index) => <article key={record.id}><header><span>{isRTL ? `٠${index + 1}` : String(index + 1).padStart(2, "0")}</span><div><strong>{t(record.title, record.titleAr)}</strong><small>{dateLabel(record)}</small></div></header><p>{record.eventOutcomeNote}</p><div><Link href={record.href} className="text-link">{t("Revisit event", "عد إلى الفعالية")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link><Link href={`/tools/customer-evidence?eventObservation=${encodeURIComponent(record.id)}`} className="button button-light">{t("Test with one customer", "اختبر مع عميل واحد")}</Link></div></article>)}</div></article>; })}</div><footer><Link href="/events" className="button button-light">{t("Open event ledger", "افتح سجل الفعاليات")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link><p>{t("Only the three latest source notes in each label are shown here. Activity retains every original event record.", "تُعرض هنا فقط أحدث ثلاث ملاحظات مصدر في كل تسمية. يحتفظ النشاط بكل سجل فعالية أصلي.")}</p></footer></section>;
}

function DecisionComparisonDesk({ records, onClear }: { records: WorkflowRecord[]; onClear: () => void }) {
  const { t, isRTL } = useLocale();
  const outcomeLabel = (record: WorkflowRecord) => !record.outcome ? t("Open review", "مراجعة مفتوحة") : record.outcome === "keep" ? t("Keep", "استمر") : record.outcome === "change" ? t("Change", "غيّر") : t("Stop", "أوقف");
  const reviewLabel = (record: WorkflowRecord) => t(record.reviewDate ?? record.reviewDue ?? "No dated review", record.reviewDateAr ?? record.reviewDue ?? "لا مراجعة مؤرخة");
  const fields = [
    { label: t("Status", "الحالة"), value: (record: WorkflowRecord) => outcomeLabel(record) },
    { label: t("Source", "المصدر"), value: (record: WorkflowRecord) => decisionSource(record, t) },
    { label: t("Retained evidence", "الدليل المحتفظ به"), value: (record: WorkflowRecord) => archiveExcerpt(record, t) },
    { label: t("Original test", "الاختبار الأصلي"), value: (record: WorkflowRecord) => record.nextAction ? t(record.nextAction, record.nextActionAr ?? record.nextAction) : t("Open the source record", "افتح سجل المصدر") },
    { label: t("Review timing", "توقيت المراجعة"), value: (record: WorkflowRecord) => reviewLabel(record) },
    { label: t("Working principle", "مبدأ العمل"), value: (record: WorkflowRecord) => record.operatingPrinciple?.rule ?? t("No working principle retained", "لا يوجد مبدأ عمل محتفظ به") },
  ];
  return <section className="decision-comparison-desk" aria-labelledby="decision-comparison-title"><header className="decision-comparison-desk__heading"><div><SectionLabel>{t("Decision comparison desk", "مكتب مقارنة القرارات")}</SectionLabel><h2 id="decision-comparison-title">{t("Place the original evidence beside itself before you reuse it.", "ضع الدليل الأصلي بجانب نفسه قبل أن تعيد استخدامه.")}</h2><p>{t("This desk compares the retained fields of two saved decisions. It does not decide which one is better or claim that two records form a pattern.", "يقارن هذا المكتب الحقول المحتفظ بها لقرارين محفوظين. لا يقرر أيهما أفضل ولا يدعي أن سجلين يشكلان نمطا.")}</p></div><button type="button" className="text-link" onClick={onClear}>{t("Clear comparison", "امسح المقارنة")}</button></header><div className="decision-comparison-desk__rule"><span className="mono">{t("COMPARISON BOUNDARY", "حد المقارنة")}</span><p>{t("Open records remain incomplete context. Read the source and its review timing before moving a new decision.", "تظل السجلات المفتوحة سياقا غير مكتمل. اقرأ المصدر وتوقيت مراجعته قبل تحريك قرار جديد.")}</p></div><div className="decision-comparison-desk__grid">{records.map((record, index) => <article key={record.id} className={record.outcome ? "is-" + record.outcome : "is-open"}><header><span>{t("Record", "سجل")} {isRTL ? "٠" + String(index + 1) : String(index + 1).padStart(2, "0")}</span><strong>{outcomeLabel(record)}</strong></header><div className="decision-comparison-desk__record-title"><span className="mono">{decisionSource(record, t)}</span><h3>{t(record.title, record.titleAr)}</h3></div><dl>{fields.map((field) => <div key={field.label}><dt>{field.label}</dt><dd>{field.value(record)}</dd></div>)}</dl><div className="decision-comparison-desk__actions"><Link href="/dashboard/decision-review" className="text-link">{t("Open decision", "افتح القرار")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link><Link href={`/tools/customer-evidence?reuse=${encodeURIComponent(record.id)}`} className="button button-dark">{t("Reuse as new customer test", "أعد استخدامه كاختبار عميل جديد")}</Link>{record.href.startsWith("/tools/") && <Link href={record.href} className="button button-light">{t("Reopen source", "أعد فتح المصدر")}</Link>}</div></article>)}</div></section>;
}

type EvidenceReviewLane = "overdue" | "upcoming" | "undated";

function MonthlyEvidenceReviewDigest({ records }: { records: WorkflowRecord[] }) {
  const { t, isRTL, formatNum } = useLocale();
  const today = new Date().toISOString().slice(0, 10);
  const nextWeek = new Date(Date.now() + 7 * 86_400_000).toISOString().slice(0, 10);
  const openDecisions = records.filter((record) => record.kind === "decision" && !record.outcome);
  const laneRecords: Record<EvidenceReviewLane, WorkflowRecord[]> = {
    overdue: openDecisions.filter((record) => Boolean(record.reviewDue && record.reviewDue < today)).sort((a, b) => (a.reviewDue ?? "").localeCompare(b.reviewDue ?? "")),
    upcoming: openDecisions.filter((record) => Boolean(record.reviewDue && record.reviewDue >= today && record.reviewDue <= nextWeek)).sort((a, b) => (a.reviewDue ?? "").localeCompare(b.reviewDue ?? "")),
    undated: openDecisions.filter((record) => !record.reviewDue).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)),
  };
  const later = openDecisions.filter((record) => Boolean(record.reviewDue && record.reviewDue > nextWeek));
  const lanes: Array<{ id: EvidenceReviewLane; label: string; labelAr: string; title: string; titleAr: string; copy: string; copyAr: string }> = [
    { id: "overdue", label: "OVERDUE EVIDENCE", labelAr: "دليل متأخر", title: "Name what the evidence changes.", titleAr: "سمِ ما الذي يغيره الدليل.", copy: "These records passed their stated review point. Reopen the original test before deciding what to keep, change, or stop.", copyAr: "تجاوزت هذه السجلات نقطة مراجعتها المحددة. أعد فتح الاختبار الأصلي قبل تحديد ما ستبقيه أو تغيره أو توقفه." },
    { id: "upcoming", label: "NEXT 7 DAYS", labelAr: "الأيام السبعة التالية", title: "Protect the next review point.", titleAr: "احمِ نقطة المراجعة التالية.", copy: "These tests have a named near-term review. Keep the evidence and owner close before the deadline becomes a missed learning loop.", copyAr: "لهذه الاختبارات مراجعة قريبة محددة. أبقِ الدليل والمالك قريبين قبل أن يتحول الموعد إلى حلقة تعلم مفقودة." },
    { id: "undated", label: "MISSING REVIEW DATE", labelAr: "تاريخ مراجعة مفقود", title: "Turn retained work into a calendar point.", titleAr: "حوّل العمل المحتفظ به إلى نقطة في التقويم.", copy: "These saved decisions have context but no visible review date. Set one before opening another experiment.", copyAr: "تحتوي هذه القرارات المحفوظة على سياق لكن من دون تاريخ مراجعة واضح. حدد واحدا قبل فتح تجربة أخرى." },
  ];
  const reviewDate = (record: WorkflowRecord, lane: EvidenceReviewLane) => {
    if (lane === "overdue") return t(`Review was due ${record.reviewDue}.`, `كانت المراجعة مستحقة في ${record.reviewDue}.`);
    if (lane === "upcoming") return t(`Review due ${record.reviewDue}.`, `المراجعة مستحقة في ${record.reviewDue}.`);
    return t("No review date retained.", "لم يتم الاحتفاظ بتاريخ للمراجعة.");
  };
  if (!openDecisions.length) return null;
  return <section className="monthly-evidence-digest" aria-labelledby="monthly-evidence-digest-title"><header className="monthly-evidence-digest__heading"><div><SectionLabel>{t("Monthly evidence review", "مراجعة الأدلة الشهرية")}</SectionLabel><h2 id="monthly-evidence-digest-title">{t("Bring the evidence due for a decision back into view.", "أعد الدليل المستحق لقرار إلى نطاق الرؤية.")}</h2><p>{t("This is a review queue, not a priority score. It surfaces only open decisions whose evidence needs a dated next move.", "هذه قائمة مراجعة، وليست درجة أولوية. تعرض فقط القرارات المفتوحة التي يحتاج دليلها إلى خطوة تالية مؤرخة.")}</p></div><dl><div><dt>{t("Overdue", "متأخر")}</dt><dd>{formatNum(laneRecords.overdue.length)}</dd></div><div><dt>{t("Next 7 days", "الأيام السبعة التالية")}</dt><dd>{formatNum(laneRecords.upcoming.length)}</dd></div><div><dt>{t("No date", "دون تاريخ")}</dt><dd>{formatNum(laneRecords.undated.length)}</dd></div></dl></header><div className="monthly-evidence-digest__boundary"><span className="mono">{t("REVIEW BOUNDARY", "حد المراجعة")}</span><p>{t(`${formatNum(later.length)} open decision${later.length === 1 ? " is" : "s are"} scheduled beyond the next seven days and deliberately kept out of this immediate queue.`, `يوجد ${formatNum(later.length)} قرار${later.length === 1 ? " مفتوح" : "ات مفتوحة"} بموعد بعد الأيام السبعة التالية، ولذلك تُترك عمدا خارج هذه القائمة الفورية.`)}</p></div><div className="monthly-evidence-digest__lanes">{lanes.map((lane) => { const shown = laneRecords[lane.id]; return <article key={lane.id} className={`monthly-evidence-digest__lane is-${lane.id}`}><div className="monthly-evidence-digest__lane-intro"><span className="mono">{t(lane.label, lane.labelAr)}</span><h3>{t(lane.title, lane.titleAr)}</h3><p>{t(lane.copy, lane.copyAr)}</p></div>{shown.length ? <div className="monthly-evidence-digest__records">{shown.slice(0, 3).map((record) => <article key={record.id}><header><span>{t(decisionSource(record, t), decisionSource(record, t))}</span><strong>{reviewDate(record, lane.id)}</strong></header><h4>{t(record.title, record.titleAr)}</h4><p>{archiveExcerpt(record, t)}</p><dl><div><dt>{t("Original test", "الاختبار الأصلي")}</dt><dd>{t(record.nextAction ?? "Open the source record", record.nextActionAr ?? "افتح سجل المصدر")}</dd></div><div><dt>{t("Owner", "المالك")}</dt><dd>{t(record.owner ?? "Founder", record.ownerAr ?? "المؤسس")}</dd></div></dl><div className="monthly-evidence-digest__actions"><Link href="/dashboard/decision-review" className="button button-dark">{t("Review decision", "راجع القرار")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link><Link href={record.href} className="text-link">{t("Open source", "افتح المصدر")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></div></article>)}</div> : <div className="monthly-evidence-digest__empty"><strong>{t("No open review in this lane.", "لا توجد مراجعة مفتوحة في هذا المسار.")}</strong><p>{t("Keep the current evidence close to its next dated move.", "أبقِ الدليل الحالي قريبا من خطوته التالية المؤرخة.")}</p></div>}</article>; })}</div><footer><p>{t("Completed Keep, Change, and Stop outcomes remain in the Founder Learning Archive. They are intentionally excluded here so this queue stays focused on work that still needs a decision.", "تبقى نتائج استمر وغيّر وأوقف المكتملة في أرشيف تعلم المؤسس. تُستبعد هنا عمدا حتى تظل هذه القائمة مركزة على العمل الذي ما زال يحتاج إلى قرار.")}</p><Link href="/dashboard/weekly-review" className="button button-light">{t("Open weekly review", "افتح المراجعة الأسبوعية")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link></footer></section>;
}

function CrossToolDecisionArchive({ records }: { records: WorkflowRecord[] }) {
  const { t, isRTL, formatNum } = useLocale();
  const [query, setQuery] = useState("");
  const [outcome, setOutcome] = useState<ArchiveOutcomeFilter>("all");
  const [source, setSource] = useState<ArchiveSourceFilter>("all");
  const [comparisonIds, setComparisonIds] = useState<string[]>([]);
  const normalisedQuery = query.trim().toLocaleLowerCase();
  const matches = useMemo(() => records.filter((record) => {
    const sourceType: ArchiveSourceFilter = record.href.startsWith("/tools/") ? "tool" : "workspace";
    const haystack = [record.title, record.titleAr, record.evidence, record.weeklyReflection, record.nextAction, record.nextActionAr, record.operatingPrinciple?.rule, record.operatingPrinciple?.scope, record.operatingPrinciple?.applyNext].filter(Boolean).join(" ").toLocaleLowerCase();
    const matchesSearch = !normalisedQuery || haystack.includes(normalisedQuery);
    const matchesOutcome = outcome === "all" || outcome === "open" ? (outcome === "open" ? !record.outcome : true) : record.outcome === outcome;
    const matchesSource = source === "all" || sourceType === source;
    return matchesSearch && matchesOutcome && matchesSource;
  }).sort((a, b) => (b.outcomeAt ?? b.updatedAt).localeCompare(a.outcomeAt ?? a.updatedAt)), [records, normalisedQuery, outcome, source]);
  const comparisonRecords = comparisonIds.map((id) => records.find((record) => record.id === id)).filter((record): record is WorkflowRecord => Boolean(record));
  const outcomeLabel = (record: WorkflowRecord) => !record.outcome ? t("Open review", "مراجعة مفتوحة") : record.outcome === "keep" ? t("Keep", "استمر") : record.outcome === "change" ? t("Change", "غيّر") : t("Stop", "أوقف");
  const dateLabel = (record: WorkflowRecord) => new Intl.DateTimeFormat(isRTL ? "ar-EG" : "en-GB", { month: "short", day: "numeric", year: "numeric" }).format(new Date(record.outcomeAt ?? record.updatedAt));
  const toggleComparison = (id: string) => setComparisonIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current.slice(-1), id]);
  const comparisonMessage = comparisonRecords.length === 0 ? t("Choose two saved decisions to compare their original context.", "اختر قرارين محفوظين لمقارنة سياقهما الأصلي.") : comparisonRecords.length === 1 ? t("Choose one more saved decision. A third choice replaces the earliest selection.", "اختر قرارا محفوظا آخر. الاختيار الثالث يستبدل الاختيار الأقدم.") : t("Two records are ready for a bounded field-by-field comparison.", "سجلان جاهزان لمقارنة محددة حقلا بحقل.");
  return <section className="cross-tool-decision-archive" aria-labelledby="cross-tool-decision-archive-title"><header className="cross-tool-decision-archive__heading"><div><SectionLabel>{t("Cross-tool decision archive", "أرشيف القرارات عبر الأدوات")}</SectionLabel><h2 id="cross-tool-decision-archive-title">{t("Find the work you already tested before you start again.", "اعثر على العمل الذي اختبرته قبل أن تبدأ من جديد.")}</h2><p>{t("Search retained decision context across founder tools and workspace work. Each result keeps its source, original evidence, review timing, and direct return path.", "ابحث في سياق القرار المحتفظ به عبر أدوات المؤسس ومساحة العمل. تحتفظ كل نتيجة بمصدرها ودليلها الأصلي وتوقيت مراجعتها ومسار العودة المباشر.")}</p></div><div className="cross-tool-decision-archive__metric"><strong>{formatNum(records.length)}</strong><span>{t("saved decisions", "قرارات محفوظة")}</span></div></header><div className="cross-tool-decision-archive__rule"><span className="mono">{t("RETRIEVAL RULE", "قاعدة الاسترجاع")}</span><p>{t("Search surfaces the original record. It does not combine matches into a conclusion, score evidence, or create a new decision.", "يعرض البحث السجل الأصلي. لا يجمع المطابقات في استنتاج، ولا يسجل الدليل، ولا ينشئ قرارا جديدا.")}</p></div><div className="cross-tool-decision-archive__controls"><label><span>{t("Search retained context", "ابحث في السياق المحتفظ به")}</span><div><Search size={15} aria-hidden="true" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("Title, evidence, reflection, or next action", "العنوان أو الدليل أو الانعكاس أو الخطوة التالية")} /></div></label><div className="cross-tool-decision-archive__filter-group"><span>{t("Outcome", "النتيجة")}</span><div role="toolbar" aria-label={t("Filter archive by outcome", "تصفية الأرشيف حسب النتيجة")}>{(["all", "open", "keep", "change", "stop"] as ArchiveOutcomeFilter[]).map((option) => <button type="button" key={option} className={outcome === option ? "active" : ""} aria-pressed={outcome === option} onClick={() => setOutcome(option)}>{option === "all" ? t("All", "الكل") : option === "open" ? t("Open", "مفتوح") : option === "keep" ? t("Keep", "استمر") : option === "change" ? t("Change", "غيّر") : t("Stop", "أوقف")}</button>)}</div></div><div className="cross-tool-decision-archive__filter-group"><span>{t("Source", "المصدر")}</span><div role="toolbar" aria-label={t("Filter archive by source", "تصفية الأرشيف حسب المصدر")}>{(["all", "tool", "workspace"] as ArchiveSourceFilter[]).map((option) => <button type="button" key={option} className={source === option ? "active" : ""} aria-pressed={source === option} onClick={() => setSource(option)}>{option === "all" ? t("All sources", "كل المصادر") : option === "tool" ? t("Founder tools", "أدوات المؤسس") : t("Workspace", "مساحة العمل")}</button>)}</div></div></div><div className="cross-tool-decision-archive__comparison-prompt"><div><span className="mono">{t("SELECT TWO RECORDS", "اختر سجلين")}</span><p>{comparisonMessage}</p></div><strong>{formatNum(comparisonRecords.length)} / {formatNum(2)}</strong></div><div className="cross-tool-decision-archive__results" aria-live="polite"><div className="cross-tool-decision-archive__results-label"><span>{normalisedQuery ? t("Matches for “" + query.trim() + "”", "مطابقات لـ «" + query.trim() + "»") : t("Latest retained decisions", "أحدث القرارات المحتفظ بها")}</span><strong>{formatNum(matches.length)} {t(matches.length === 1 ? "record" : "records", matches.length === 1 ? "سجل" : "سجلات")}</strong></div>{matches.slice(0, 8).map((record) => { const selected = comparisonIds.includes(record.id); return <article key={record.id} className={record.outcome ? "is-" + record.outcome : "is-open"}><div className="cross-tool-decision-archive__status"><span>{outcomeLabel(record)}</span><small>{dateLabel(record)}</small></div><div className="cross-tool-decision-archive__copy"><span className="mono">{decisionSource(record, t)}</span><h3>{t(record.title, record.titleAr)}</h3><p>{archiveExcerpt(record, t)}</p></div><dl><div><dt>{t("Original test", "الاختبار الأصلي")}</dt><dd>{record.nextAction ? t(record.nextAction, record.nextActionAr ?? record.nextAction) : t("Open source record", "افتح سجل المصدر")}</dd></div><div><dt>{t("Review", "المراجعة")}</dt><dd>{t(record.reviewDate ?? record.reviewDue ?? "No dated review", record.reviewDateAr ?? record.reviewDue ?? "لا مراجعة مؤرخة")}</dd></div></dl><div className="cross-tool-decision-archive__actions"><button type="button" className={selected ? "button button-dark" : "button button-light"} aria-pressed={selected} onClick={() => toggleComparison(record.id)}>{selected ? t("Selected for comparison", "محدد للمقارنة") : t("Add to comparison", "أضف للمقارنة")}</button><Link href="/dashboard/decision-review" className="text-link">{t("Open decision", "افتح القرار")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link>{record.href.startsWith("/tools/") && <Link href={record.href} className="button button-light">{t("Reopen source", "أعد فتح المصدر")}</Link>}</div></article>; })}{matches.length === 0 && <div className="cross-tool-decision-archive__empty"><strong>{t("No retained decision matches these filters.", "لا يطابق أي قرار محتفظ به هذه الفلاتر.")}</strong><p>{t("Try a title, an exact evidence phrase, or clear one filter. The archive only searches saved decision records.", "جرّب عنوانا أو عبارة دليل دقيقة أو أزل فلترًا واحدا. يبحث الأرشيف فقط في سجلات القرار المحفوظة.")}</p><button type="button" className="text-link" onClick={() => { setQuery(""); setOutcome("all"); setSource("all"); }}>{t("Clear archive filters", "امسح فلاتر الأرشيف")}</button></div>}</div>{comparisonRecords.length === 2 && <DecisionComparisonDesk records={comparisonRecords} onClear={() => setComparisonIds([])} />}</section>;
}

function CompletedToolExperimentArchive({ records }: { records: WorkflowRecord[] }) {
  const { t, isRTL, formatNum } = useLocale();
  const [outcome, setOutcome] = useState<LearningFilter>("all");
  const [source, setSource] = useState("all");
  const [comparisonIds, setComparisonIds] = useState<string[]>([]);
  const completed = records.filter((record) => record.kind === "decision" && Boolean(record.outcome) && record.href.startsWith("/tools/")).sort((a, b) => (b.outcomeAt ?? b.updatedAt).localeCompare(a.outcomeAt ?? a.updatedAt));
  const sourceSlug = (record: WorkflowRecord) => record.href.split("/").filter(Boolean).at(-1) ?? "tool";
  const sources = Array.from(new Set(completed.map(sourceSlug)));
  const shown = completed.filter((record) => (outcome === "all" || record.outcome === outcome) && (source === "all" || sourceSlug(record) === source));
  const comparisonRecords = comparisonIds.map((id) => completed.find((record) => record.id === id)).filter((record): record is WorkflowRecord => Boolean(record));
  const outcomeLabel = (record: WorkflowRecord) => record.outcome === "keep" ? t("Keep", "استمر") : record.outcome === "change" ? t("Change", "غيّر") : t("Stop", "أوقف");
  const sourceLabel = (slug: string) => decisionSource(completed.find((record) => sourceSlug(record) === slug) ?? completed[0], t);
  const formatDate = (record: WorkflowRecord) => new Intl.DateTimeFormat(isRTL ? "ar-EG" : "en-GB", { month: "short", day: "numeric", year: "numeric" }).format(new Date(record.outcomeAt ?? record.updatedAt));
  const toggleComparison = (id: string) => setComparisonIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current.slice(-1), id]);
  if (!completed.length) return null;
  return <section className="completed-tool-experiment-archive" aria-labelledby="completed-tool-experiment-title"><header className="completed-tool-experiment-archive__heading"><div><SectionLabel>{t("Completed tool experiments", "تجارب الأدوات المكتملة")}</SectionLabel><h2 id="completed-tool-experiment-title">{t("Return to the finished test before you repeat the work.", "عد إلى الاختبار المكتمل قبل أن تكرر العمل.")}</h2><p>{t("This archive contains only closed founder-tool decisions. Each entry keeps the original evidence, test, outcome, and recovery path instead of reducing work to a success score.", "يحتوي هذا الأرشيف على قرارات أدوات المؤسس المغلقة فقط. يحتفظ كل سجل بالدليل والاختبار والنتيجة ومسار الاسترجاع الأصلي بدلا من اختزال العمل في درجة نجاح.")}</p></div><div className="completed-tool-experiment-archive__metric"><strong>{formatNum(completed.length)}</strong><span>{t("closed tool tests", "اختبارات أدوات مغلقة")}</span></div></header><div className="completed-tool-experiment-archive__rule"><span className="mono">{t("ARCHIVE BOUNDARY", "حد الأرشيف")}</span><p>{t("Only explicit Keep, Change, and Stop outcomes appear here. The archive does not infer a pattern, rank an outcome, or prescribe the next experiment.", "تظهر هنا فقط النتائج الصريحة: استمر وغيّر وأوقف. لا يستنتج الأرشيف نمطا ولا يرتب نتيجة ولا يصف التجربة التالية.")}</p></div><div className="completed-tool-experiment-archive__filters"><div role="toolbar" aria-label={t("Filter completed experiments by outcome", "تصفية التجارب المكتملة حسب النتيجة")}><span>{t("Outcome", "النتيجة")}</span>{(["all", "keep", "change", "stop"] as LearningFilter[]).map((option) => <button type="button" key={option} className={outcome === option ? "is-active" : ""} aria-pressed={outcome === option} onClick={() => setOutcome(option)}>{option === "all" ? t("All outcomes", "كل النتائج") : option === "keep" ? t("Keep", "استمر") : option === "change" ? t("Change", "غيّر") : t("Stop", "أوقف")}</button>)}</div><div role="toolbar" aria-label={t("Filter completed experiments by source", "تصفية التجارب المكتملة حسب المصدر")}><span>{t("Source tool", "الأداة المصدر")}</span><button type="button" className={source === "all" ? "is-active" : ""} aria-pressed={source === "all"} onClick={() => setSource("all")}>{t("All tools", "كل الأدوات")}</button>{sources.map((slug) => <button type="button" key={slug} className={source === slug ? "is-active" : ""} aria-pressed={source === slug} onClick={() => setSource(slug)}>{sourceLabel(slug)}</button>)}</div></div><div className="completed-tool-experiment-archive__comparison"><div><span className="mono">{t("SELECT TWO CLOSED TESTS", "اختر اختبارين مغلقين")}</span><p>{comparisonRecords.length === 0 ? t("Choose two records to place their retained context side by side.", "اختر سجلين لوضع سياقهما المحتفظ به جنبا إلى جنب.") : comparisonRecords.length === 1 ? t("Choose one more closed test. A third choice replaces the earliest selection.", "اختر اختبارا مغلقا آخر. الاختيار الثالث يستبدل الاختيار الأقدم.") : t("Two closed tests are ready for a field-by-field comparison.", "اختباران مغلقان جاهزان لمقارنة حقلا بحقل.")}</p></div><strong>{formatNum(comparisonRecords.length)} / {formatNum(2)}</strong></div><div className="completed-tool-experiment-archive__records" aria-live="polite">{shown.map((record) => { const selected = comparisonIds.includes(record.id); return <article key={record.id} className={`is-${record.outcome}`}><header><span>{outcomeLabel(record)}</span><small>{formatDate(record)}</small></header><div className="completed-tool-experiment-archive__copy"><span className="mono">{decisionSource(record, t)}</span><h3>{t(record.title, record.titleAr)}</h3><p>{archiveExcerpt(record, t)}</p></div><dl><div><dt>{t("Original test", "الاختبار الأصلي")}</dt><dd>{t(record.nextAction ?? "Open the source record", record.nextActionAr ?? "افتح السجل المصدر")}</dd></div><div><dt>{t("Working rule", "قاعدة العمل")}</dt><dd>{record.operatingPrinciple?.rule ?? record.knowledgeGuidance?.claim ?? t("No working rule retained", "لا توجد قاعدة عمل محتفظ بها")}</dd></div></dl><div className="completed-tool-experiment-archive__actions"><button type="button" className={selected ? "button button-dark" : "button button-light"} aria-pressed={selected} onClick={() => toggleComparison(record.id)}>{selected ? t("Selected for comparison", "محدد للمقارنة") : t("Add to comparison", "أضف للمقارنة")}</button><Link href={record.href} className="button button-light">{t("Reopen workbench", "أعد فتح طاولة العمل")}</Link>{record.href.includes("/pricing") && <Link href={`/tools/pricing?outcome=${encodeURIComponent(record.id)}`} className="text-link">{t("Open fresh pricing test", "افتح اختبار تسعير جديد")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link>}<Link href="/dashboard/decision-review" className="text-link">{t("Review decision", "راجع القرار")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></div></article>; })}</div>{shown.length === 0 && <div className="completed-tool-experiment-archive__empty"><strong>{t("No completed tool experiment matches these filters.", "لا تطابق أي تجربة أداة مكتملة هذه الفلاتر.")}</strong><button type="button" className="text-link" onClick={() => { setOutcome("all"); setSource("all"); }}>{t("Clear archive filters", "امسح فلاتر الأرشيف")}</button></div>}{comparisonRecords.length === 2 && <DecisionComparisonDesk records={comparisonRecords} onClear={() => setComparisonIds([])} />}</section>;
}

